import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Seratus kilobyte adalah ukuran file paling berguna di internet. Ia cukup kecil untuk formulir unggah apa pun dan cukup besar untuk tampak bagus.</p>\n<p>CV, portal lowongan, thumbnail blog, dan grafis email semuanya hidup nyaman di 100KB. Inilah ukuran tempat kualitas dan kemudahan bertemu.</p>\n<p>Panduan ini menjelaskan kenapa 100KB mendapatkan reputasi itu, bagaimana kompresi mencapainya, dan cara mendapatkan hasil setajam mungkin.</p>\n<h2 id=\"why-100kb-is-the-sweet-spot\">Kenapa 100KB Adalah Titik Ideal</h2>\n<p>Kebanyakan formulir unggah membatasi file di antara 50KB sampai 500KB. File 100KB lolos hampir semuanya tanpa pikir panjang.</p>\n<p>Di saat yang sama, 100KB menyimpan cukup data supaya foto tampak bersih. Wajah tetap alami, teks tetap terbaca, dan warna tetap halus.</p>\n<p>Angka ini juga ramah untuk koneksi lambat. Gambar 100KB termuat dalam sepersekian detik, bahkan pada sinyal ponsel yang lemah.</p>\n<p>Kombinasi itu jarang ada. Ukuran yang lebih kecil tampak lebih buruk, ukuran yang lebih besar lebih sering ditolak, dan 100KB menembus di tengah-tengahnya.</p>\n<h2 id=\"what-fits-in-100kb\">Apa Saja yang Muat Nyaman di 100KB?</h2>\n<p>Foto kepala muat dengan mudah. Potret pada dimensi web normal menjaga detailnya di 100KB, termasuk rambut, kacamata, dan tekstur pakaian.</p>\n<p>Thumbnail blog juga muat. Gambar fitur selebar 1200 piksel di 100KB tampak tajam di setiap layar tempat ia benar-benar tampil.</p>\n<p>Tangkapan layar juga nyaman di 100KB. Teks antarmuka tetap terbaca, dan itulah hal pertama yang gagal pada ukuran yang lebih kecil.</p>\n<p>Hanya gambar yang sangat detail yang kesulitan. Infografis yang padat atau lanskap lebar dengan daun-daun halus mungkin butuh 200KB supaya tetap renyah.</p>\n<h2 id=\"how-the-100kb-tool-works\">Cara Kerja Alat 100KB</h2>\n<p><a href=\"/id/kompres-gambar-menjadi-100-kb/\">Alat kompres gambar ke 100KB</a> berjalan sepenuhnya di browser Anda. Gambar Anda tidak pernah diunggah ke server.</p>\n<p>Ia memakai pencarian kualitas biner. Alat menguji berbagai tingkat kualitas, mempersempit sampai menemukan pengaturan tertinggi yang tetap mendarat di bawah 100KB.</p>\n<p>Kualitas didahulukan. Alat baru mengurangi dimensi piksel ketika menurunkan kualitas saja tidak bisa mencapai target.</p>\n<p>Masukan sampai 25MB diterima, termasuk file JPG, PNG, WebP, dan HEIC. Foto ponsel yang langsung dari kamera bisa dipakai begitu saja.</p>\n<h2 id=\"quality-at-100kb\">Kualitas Gambar di 100KB</h2>\n<p>Kebanyakan penonton tidak bisa membedakan foto 100KB dari aslinya. Perbedaannya baru muncul ketika Anda memperbesar dengan dekat.</p>\n<p>Warna kulit adalah ujian terbaik. Di 100KB, warna kulit tetap halus dan alami, tanpa bercak-bercak yang muncul di 50KB.</p>\n<p>Tepi yang tajam juga bertahan. Bingkai kacamata, perhiasan, dan teks cetak menjaga ketegasannya pada ukuran ini.</p>\n<p>Latar adalah satu tempat yang perlu diperhatikan. Langit bergradasi halus bisa menampilkan pita yang samar, meskipun halus di 100KB.</p>\n<h2 id=\"jpg-vs-png-vs-webp-100kb\">JPG vs PNG vs WebP di 100KB</h2>\n<p>JPG adalah pilihan bawaan untuk foto di 100KB. Ia diterima di mana-mana dan menangani warna yang halus dengan baik.</p>\n<p>WebP sering menghasilkan hasil yang sedikit lebih bersih pada ukuran yang sama. Kendalanya adalah kompatibilitas: sebagian portal dan sistem lama menolak file WebP.</p>\n<p>PNG cocok untuk grafis, bukan foto. Logo atau diagram berwarna datar tetap tajam dalam PNG, tetapi foto dalam PNG membuang anggaran.</p>\n<p>Alat bisa mengubah otomatis PNG besar menjadi JPG atau WebP. Satu tombol itu sering mengubah kompresi yang gagal menjadi lolos dengan bersih.</p>\n<h2 id=\"resumes-and-job-portals\">CV dan Portal Lowongan</h2>\n<p>Portal lowongan adalah alasan paling umum orang butuh 100KB. Foto CV, contoh portofolio, atau pindaian sertifikat semuanya menghadapi batas yang sama.</p>\n<p>Foto kepala di 100KB tampak profesional. Perekrut melihat wajah yang jelas, bukan kotak berpiksel, dan itu lebih penting daripada yang diakui banyak orang.</p>\n<p>Pindaian sertifikat butuh perhatian. Teks cetak yang kecil harus tetap terbaca, jadi lihat pratinjau hasilnya dan perbesar sebelum mengirim.</p>\n<p>Jika portal menerima WebP, gunakan untuk foto. Jika ia hanya mencantumkan JPG, tetaplah memakai JPG dan biarkan pencarian kualitas yang bekerja.</p>\n<h2 id=\"websites-and-blogs\">Website dan Blog</h2>\n<p>Thumbnail blog di 100KB termuat cepat dan tampak tajam. Halaman dengan sepuluh thumbnail berbobot sekitar 1MB, dan kebanyakan koneksi menanganinya dengan mudah.</p>\n<p>Mesin pencari menghargai halaman yang cepat. Gambar biasanya bagian terberat dari halaman, jadi menjaganya di sekitar 100KB langsung membantu waktu muat.</p>\n<p>Gambar utama boleh lebih besar, tetapi gambar pendukung jarang perlu. Gambar pendukung 100KB tidak terlihat berbeda kualitasnya bagi kebanyakan pembaca.</p>\n<p>Untuk optimasi halaman penuh, pasangkan alat 100KB dengan <a href=\"/id/optimalkan-gambar-untuk-web/\">alat optimasi gambar web</a>, yang menambah preset dan HTML siap tempel.</p>\n<h2 id=\"email-and-newsletters\">Email dan Buletin</h2>\n<p>Klien email lambat menampilkan gambar yang berat. Grafis 100KB muncul hampir seketika di kotak masuk, sedangkan yang 2MB bisa tersendat.</p>\n<p>Buletin dengan beberapa gambar paling diuntungkan. Lima gambar di 100KB totalnya 500KB, sehingga seluruh email tetap ringan.</p>\n<p>Pertahankan format yang sederhana untuk email. JPG adalah pilihan paling aman, karena sebagian klien email menangani WebP dengan buruk.</p>\n<p>Selalu uji email dengan mengirimkannya ke diri Anda sendiri dulu. Periksa gambar termuat cepat dan tidak ada yang tampak meregang atau buram.</p>\n<h2 id=\"batch-compression\">Mengompres Banyak Gambar ke 100KB</h2>\n<p>Anda bisa mengompres seluruh folder gambar ke 100KB dalam satu batch. Jatuhkan semuanya sekaligus, dan masing-masing diproses ke target yang sama.</p>\n<p>Hasilnya terunduh bersamaan sebagai file ZIP. Itu menjaga kumpulan thumbnail atau foto portofolio tetap teratur di satu tempat.</p>\n<p>Mode batch ideal untuk migrasi blog. Mengubah lima puluh thumbnail lama satu per satu akan memakan waktu seharian; satu batch hanya butuh beberapa menit.</p>\n<p>Periksa beberapa hasil sebelum mengunduh seluruh ZIP. Jika satu gambar tampak lembut, sesuaikan formatnya dan jalankan ulang hanya file itu.</p>\n<h2 id=\"common-mistakes\">Kesalahan Umum di 100KB</h2>\n<p>Memulai dari file yang sudah dikompres adalah kesalahan terbesar. Setiap putaran kompresi menambah kerusakan, jadi selalu gunakan originalnya.</p>\n<p>Mengunci format ke PNG untuk foto adalah kesalahan lain. PNG tidak bisa mencapai 100KB dengan bersih untuk foto yang detail, dan alat akan memberi peringatan.</p>\n<p>Lupa memeriksa hasil juga umum terjadi. Ukuran file bisa saja benar sementara gambarnya buram, jadi lihat pratinjau sebelum mengunduh.</p>\n<p>Terakhir, jangan menganggap setiap portal menerima WebP. Periksa dulu format yang diterima, atau Anda bisa mengompres dua kali.</p>\n<h2 id=\"when-100kb-is-not-enough\">Ketika 100KB Tidak Cukup</h2>\n<p>Gambar besar yang detail kadang butuh ruang lebih. Infografis lebar dengan label kecil bisa tetap buram di 100KB.</p>\n<p>Pekerjaan cetak juga butuh lebih. Foto yang ditujukan untuk kertas harus tetap beresolusi tinggi, dan 100KB adalah ukuran web, bukan ukuran cetak.</p>\n<p>Dalam kasus itu, naiklah ke <a href=\"/id/kompres-gambar-menjadi-200-kb/\">alat kompres 200KB</a> atau <a href=\"/id/kompres-gambar-menjadi-500-kb/\">alat kompres 500KB</a>.</p>\n<p>Aturannya tetap sama: gunakan ukuran terbesar yang diizinkan situasi Anda. Kualitas sepadan dengan kilobyte ekstra ketika tersedia.</p>\n<h2 id=\"under-100kb-badge\">Lencana Di Bawah 100KB dan Jaminannya</h2>\n<p>Ketika kompresi berhasil, alat menampilkan lencana Di Bawah 100KB. Lencana itu berarti file akhirnya terukur di bawah 100KB dalam byte yang persis.</p>\n<p>Pengukuran byte yang persis penting karena portal memeriksa byte, bukan angka bulat. File yang disebut ponsel Anda 100KB mungkin sebenarnya 100,4KB.</p>\n<p>Alat membidik sedikit di bawah garis, biasanya mendarat antara 98KB sampai 99,9KB. Margin itu melindungi Anda dari perbedaan pembulatan.</p>\n<p>Jika lencana tidak muncul, file itu tidak mencapai target. Alat memberi tahu Anda dengan jujur, bukan menyerahkan file yang akan ditolak.</p>\n<p>Jangan pernah mengirim file tanpa lencana itu. Percobaan ulang yang cepat dengan format berbeda jauh lebih baik daripada unggahan yang ditolak.</p>\n<h2 id=\"dimension-scaling-100kb\">Cara Kerja Penskalaan Dimensi di 100KB</h2>\n<p>Penskalaan dimensi mengurangi ukuran piksel gambar Anda ketika potongan kualitas saja tidak bisa mencapai 100KB. Ia terjadi dalam langkah kecil, bukan satu lompatan besar.</p>\n<p>Alat menguji skala seperti 90 persen, 80 persen, dan seterusnya, lalu berhenti pada yang pertama kali muat. Setiap langkah mempertahankan ukuran sebesar mungkin.</p>\n<p>Langkah skala kecil biasanya tidak terlihat. Foto yang ditampilkan selebar 800 piksel tampak sama pada 720 piksel.</p>\n<p>Penskalaan paling membantu untuk original yang sangat besar. Foto selebar 4000 piksel punya jauh lebih banyak piksel daripada yang dibutuhkan layar mana pun, jadi memangkasnya tidak menghilangkan apa pun yang terlihat.</p>\n<p>Anda juga bisa mengunci dimensinya jika portal menuntut piksel yang persis. Alat kemudian akan bekerja lebih keras pada kualitas saja, dan mungkin memberi peringatan jika target tidak bisa dipenuhi.</p>\n<h2 id=\"social-media-100kb\">100KB untuk Media Sosial dan Avatar</h2>\n<p>Platform sosial mengompres unggahan Anda lagi, jadi memulai dari 100KB memberi mereka file bersih untuk dikerjakan. Original yang besar sering kembali tampak lebih buruk.</p>\n<p>Foto profil adalah kasus terbaik. Foto kepala 100KB terunggah seketika dan bertahan melewati kompresi platform itu sendiri dengan detail yang utuh.</p>\n<p>Gambar sampul butuh perhatian lebih. Mereka ditampilkan besar, jadi periksa hasilnya pada ukuran penuh sebelum mengunggahnya sebagai banner.</p>\n<p>Untuk kiriman dengan teks di atasnya, lihat pratinjau teksnya dengan teliti. Kompresi platform melembutkan huruf kecil, jadi mulailah dari file 100KB paling tajam yang bisa Anda buat.</p>\n<p>Ingatlah bahwa setiap platform punya batasnya sendiri. Periksa sebelum mengompres, karena file yang dibuat untuk satu platform mungkin tidak cocok untuk platform lain.</p>\n<h2 id=\"storing-100kb-files\">Menata File 100KB Anda</h2>\n<p>Simpan file hasil kompres dalam folder berdasarkan tujuannya. Folder untuk lamaran kerja dan folder lain untuk gambar blog mencegah tertukar.</p>\n<p>Beri nama file dengan menyertakan ukurannya. Nama seperti headshot-100kb.jpg langsung memberi tahu Anda untuk apa file itu.</p>\n<p>Selalu simpan original di folder terpisah. Salinan hasil kompres bisa dibuang; original tidak.</p>\n<p>Tinjau file simpanan sebelum menggunakannya lagi. File yang dibuat setahun lalu mungkin tidak sesuai dengan persyaratan portal yang Anda lamar sekarang.</p>\n<p>Ketika ragu, kompres baru dari originalnya. Itu hanya butuh satu menit, dan hasilnya akan persis mengikuti aturan hari ini.</p>\n<p>Sertifikat dengan teks kecil adalah ujian sesungguhnya bagi 100KB. Perbesar hasil kompres dan baca nomor registrasi, tanggal, dan nama dengan teliti, karena huruf-huruf kecil inilah yang pertama kali buram. Jika teksnya sulit dibaca, coba keluaran WebP atau naik ke 200KB, karena sertifikat yang tidak terbaca tidak ada gunanya, sebagus apa pun tampilannya.</p>\n<h2 id=\"when-to-move-up\">Kapan Naik ke 200KB</h2>\n<p>Sebagian gambar butuh lebih dari 100KB. Lanskap lebar, infografis padat, dan foto produk yang detail semuanya diuntungkan ruang ekstra.</p>\n<p>Tandanya adalah kelembutan yang terlihat. Jika teks buram atau tekstur halus menghilang di 100KB, gambar itu meminta anggaran yang lebih besar.</p>\n<p>Cetak adalah alasan lain untuk naik. File 100KB adalah ukuran web; apa pun yang ditujukan untuk kertas harus tetap jauh lebih besar.</p>\n<p>Periksa dulu tujuannya. Jika portal atau platform mengizinkan 200KB, gunakan <a href=\"/id/kompres-gambar-menjadi-200-kb/\">alat kompres 200KB</a> daripada melawan batas 100KB.</p>\n<p>Tujuannya selalu sama: ukuran terbesar yang diizinkan situasi Anda, dengan kualitas terbaik yang bisa ditampung ukuran itu.</p>\n<h2 id=\"image-weight-budgets\">Anggaran Bobot Gambar untuk Seluruh Halaman</h2>\n<p>Satu gambar 100KB memang ringan, tetapi halaman membawa banyak gambar. Sepuluh thumbnail di 100KB berbobot 1MB bersamaan, dan itu anggaran yang masuk akal untuk sebuah halaman.</p>\n<p>Tetapkan total anggaran sebelum memulai. Artikel blog dengan delapan gambar muat nyaman di bawah 1MB ketika setiap gambar bertahan di sekitar 100KB.</p>\n<p>Utamakan gambar utama. Beri ia 200KB jika memang pantas, dan pertahankan gambar pendukung di 100KB atau di bawahnya.</p>\n<p>Ukur bobot halaman yang sebenarnya setelah diterbitkan. Perkakas pengembang browser menampilkan totalnya, dan angkanya sering mengejutkan orang.</p>\n<p>Halaman yang termuat cepat mempertahankan pembaca. Bobot gambar biasanya faktor terbesar, dan 100KB per gambar adalah patokan yang bisa diandalkan.</p>\n<h2 id=\"retina-screens\">Gambar 100KB di Layar Retina dan High-DPI</h2>\n<p>Layar Retina memadatkan lebih banyak piksel ke ukuran fisik yang sama. Gambar yang tampak tajam di layar biasa bisa tampak lembut di layar Retina.</p>\n<p>Perbaikannya adalah menyajikan gambar dua kali lebih lebar dari ukuran tampilnya. Thumbnail yang ditampilkan selebar 400 piksel sebaiknya 800 piksel dalam file.</p>\n<p>Di 100KB, gambar 800 piksel tetap tampak bersih. Piksel ekstra itu memang butuh bobot file, tetapi pencarian biner menyeimbangkan kualitas dengan anggaran.</p>\n<p>Untuk thumbnail kecil, hal ini tidak terlalu penting. Untuk gambar fitur besar, perbedaan antara file standar dan file siap Retina terlihat jelas.</p>\n<p>Uji di layar high-DPI yang sebenarnya bila Anda bisa. Tangkapan layar dari hasilnya menyembunyikan kelembutan yang sedang Anda periksa.</p>\n<p>Formulir daring juga sering memakai 100KB. Pendaftaran sekolah, kursus, dan layanan pemerintah biasanya menetapkan batas ini untuk foto dan pindaian dokumen.</p>\n<p>Tanda tangan digital untuk email adalah kasus kecil yang berguna. Gambar tanda tangan 100KB tampak profesional di bawah email tanpa membuat pesan menjadi berat.</p>\n<p>Gambar sampul untuk dokumen bersama juga cocok di 100KB. Sampul proposal atau laporan yang dibagikan lewat email termuat cepat dan tetap tampak rapi.</p>\n<h2 id=\"seasonal-content\">Konten Musiman dan Menggunakan Lagi Gambar 100KB</h2>\n<p>Gambar blog dipakai ulang lintas musim. Thumbnail 100KB yang dibuat untuk satu artikel bisa muncul lagi di rangkuman, buletin, dan kartu sosial.</p>\n<p>Simpan file hasil kompres bersama artikel yang dimilikinya. Folder thumbnail bersama membuat pemakaian ulang mudah dan mencegah kompresi ganda.</p>\n<p>Periksa gambar sebelum setiap pemakaian ulang. Thumbnail yang tampak baik tahun lalu mungkin tidak cocok untuk tata letak atau potongan tahun ini.</p>\n<p>Jangan pernah mengompres ulang file yang dipakai ulang. Jika ukuran baru dibutuhkan, kembali ke original dan kompres baru.</p>\n<p>Penataan yang baik mengubah gambar 100KB menjadi aset yang bisa dipakai ulang. Sedikit disiplin penamaan sekarang menghemat waktu pengerjaan ulang nanti.</p>\n<p>Untuk langkah-langkah praktisnya, baca <a href=\"/id/blog/cara-mengecilkan-gambar-menjadi-100kb/\">Cara Mengecilkan Gambar Menjadi 100KB</a>. Untuk perbandingan kualitas per format, lihat <a href=\"/id/blog/kualitas-gambar-100kb-jpg-vs-png-vs-webp/\">Kualitas Gambar 100KB: JPG vs PNG vs WebP di 100KB</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Apakah 100KB cukup untuk foto profil yang profesional?","answer":"Ya. Foto kepala di 100KB tampak bersih dan profesional di LinkedIn, portal lowongan, dan situs perusahaan. Wajah, rambut, dan pakaian semuanya menjaga detailnya pada ukuran ini, dan file itu lolos hampir semua batas unggah."},{"question":"Bisakah saya mengompres foto 10MB menjadi 100KB?","answer":"Bisa, alat menerima masukan sampai 25MB dan bisa mengurangi foto 10MB menjadi di bawah 100KB. Pencarian biner menemukan kualitas terbaik yang muat, dan penskalaan dimensi ikut membantu jika kualitas saja tidak cukup. Bersiaplah ada sedikit pelembutan pada foto yang sangat detail."},{"question":"Apakah mengompres ke 100KB akan menghapus latar foto saya?","answer":"Tidak. Kompresi hanya mengurangi ukuran file; ia tidak mengedit isi gambar. Jika Anda butuh latarnya dihapus, gunakan dulu alat penghapus latar, lalu kompres hasilnya ke 100KB."},{"question":"Kenapa tangkapan layar PNG saya malah membesar setelah dikompres ke 100KB?","answer":"File bisa membesar ketika dikodekan ulang dalam format yang tidak cocok untuknya, dan alat memberi peringatan saat hal itu terjadi. Beralih ke JPG atau WebP biasanya memperbaikinya, karena kedua format itu menangani foto dan tangkapan layar jauh lebih efisien daripada PNG."},{"question":"Apakah alat 100KB bekerja luring?","answer":"Kompresinya sendiri berjalan secara lokal di browser Anda begitu halaman termuat, jadi tidak ada unggahan yang terjadi. Anda tetap butuh memuat halaman dulu, dan itu memerlukan koneksi internet."},{"question":"Bagaimana saya tahu gambar saya benar-benar di bawah 100KB?","answer":"Alat menampilkan ukuran hasil dan konfirmasi Di Bawah 100KB. Anda juga bisa memeriksa file unduhan di perangkat Anda, yang seharusnya terbaca sedikit di bawah 100KB, biasanya antara 98 sampai 99,9KB."}];
